16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.nio.charset.StandardCharsets;
25	import java.security.MessageDigest;
26	import java.security.NoSuchAlgorithmException;
27	import java.time.LocalDate;
28	import java.util.*;
29	
30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "city")
46	    @NotEmpty
47	    private String city;
48	
49	    @Column(name = "telephone")
50	    @NotEmpty
51	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    private String email;
56	
57	    @Column(name = "registration_date", columnDefinition = "DATE")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "customer_code")
61	    private String customerCode;
62	
63	    @Column(name = "household_id")
64	    private String householdId;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @Column(name = "household_size")
70	    private Integer householdSize;
71	
72	    @Column(name = "postcode")
73	    private String postcode;
74	
75	    @Column(name = "bulk_signup_warning")
76	    private Boolean bulkSignupWarning;
77	
78	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
79	    private Set<Pet> pets;
80	
81	    /**
82	     * Fixed city-to-region table used to derive {@link #getLocality() locality} when the postcode
83	     * is absent or in no known range. Any city not listed derives the locality {@code 'UNKNOWN'}.
84	     */
85	    private static final Map<String, String> CITY_REGION = Map.of(
86	        "Sydney", "NSW",
87	        "Melbourne", "VIC",
88	        "Brisbane", "QLD");
89	
90	    /**
91	     * Inclusive 4-digit postcode range per region, used to derive {@link #getLocality() locality}
92	     * from the postcode in preference to the city: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
93	     */
94	    private static final Map<String, int[]> REGION_POSTCODE = Map.of(
95	        "NSW", new int[] {2000, 2099},
96	        "VIC", new int[] {3000, 3099},
97	        "QLD", new int[] {4000, 4099});
98	
99	    public String getAddress() {
100	        return this.address;
101	    }
102	
103	    public void setAddress(String address) {
104	        this.address = address;
105	    }
106	
107	    public String getCity() {
108	        return this.city;
109	    }
110	
111	    public void setCity(String city) {
112	        this.city = city;
113	    }
114	
115	    public String getTelephone() {
116	        return this.telephone;
117	    }
118	
119	    public void setTelephone(String telephone) {
120	        this.telephone = telephone;
121	    }
122	
123	    public String getEmail() {
124	        return this.email;
125	    }
126	
127	    public void setEmail(String email) {
128	        this.email = email;
129	    }
130	
131	    public LocalDate getRegistrationDate() {
132	        return this.registrationDate;
133	    }
134	
135	    public void setRegistrationDate(LocalDate registrationDate) {
136	        this.registrationDate = registrationDate;
137	    }
138	
139	    public String getCustomerCode() {
140	        return this.customerCode;
141	    }
142	
143	    public void setCustomerCode(String customerCode) {
144	        this.customerCode = customerCode;
145	    }
146	
147	    /**
148	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
149	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived
150	     * from the owner's own customer code and registration date; {@code null} when either is absent.
151	     *
152	     * @return the membership number, or {@code null} when it cannot be derived
153	     */
154	    public String getMembershipNumber() {
155	        if (this.customerCode == null || this.registrationDate == null) {
156	            return null;
157	        }
158	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
159	    }
160	
161	    /**
162	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
163	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
164	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
165	     *
166	     * @return the Luhn check digit, or {@code null} when the customer code is absent
167	     */
168	    public Integer getCheckDigit() {
169	        if (this.customerCode == null) {
170	            return null;
171	        }
172	        int sum = 0;
173	        boolean dbl = true;
174	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
175	            char c = this.customerCode.charAt(i);
176	            if (c < '0' || c > '9') {
177	                continue;
178	            }
179	            int d = c - '0';
180	            if (dbl) {
181	                d *= 2;
182	                if (d > 9) {
183	                    d -= 9;
184	                }
185	            }
186	            sum += d;
187	            dbl = !dbl;
188	        }
189	        return (10 - (sum % 10)) % 10;
190	    }
191	
192	    /**
193	     * The owner's numeric membership level, derived from the values frozen at create time. It starts
194	     * at 1, gains 1 when an email address is present, gains 1 when the owner has no namesakes
195	     * ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
196	     *
197	     * @return the membership level, an integer from 1 to 3
198	     */
199	    public Integer getMembershipLevel() {
200	        int level = 1;
201	        boolean hasEmail = this.email != null && !this.email.isBlank();
202	        if (hasEmail) {
203	            level++;
204	        }
205	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
206	        if (hasNoNamesakes) {
207	            level++;
208	        }
209	        return Math.min(level, 3);
210	    }
211	
212	    /**
213	     * The owner's locality, the canonical region string. Once the owner has a
214	     * {@link #getCustomerCode() customer code} the locality is the {@code <REGION>} component of that
215	     * code (the text before the first {@code '-'}), so the locality and the identity share a single
216	     * source of truth. Before the customer code is assigned (for example while a create is still
217	     * validating the postcode) it falls back to the region the code will be built from: the
218	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
219	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
220	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
221	     *
222	     * @return the canonical region string, or {@code 'UNKNOWN'}
223	     */
224	    public String getLocality() {
225	        if (this.customerCode != null) {
226	            int dash = this.customerCode.indexOf('-');
227	            return dash >= 0 ? this.customerCode.substring(0, dash) : this.customerCode;
228	        }
229	        return deriveRegion();
230	    }
231	
232	    /**
233	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
234	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
235	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
236	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
237	     * the same region for known cities but disambiguates cities that share a name.
238	     *
239	     * @return the canonical region string, or {@code 'UNKNOWN'}
240	     */
241	    private String deriveRegion() {
242	        String region = regionFromPostcode();
243	        if (region != null) {
244	            return region;
245	        }
246	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
247	    }
248	
249	    /**
250	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
251	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
252	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
253	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
254	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
255	     * owner's region, telephone and last name. Call this once at create time and store the result via
256	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
257	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
258	     *
259	     * @return the assembled customer code
260	     */
261	    public String buildCustomerCode() {
262	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
263	    }
264	
265	    /**
266	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
267	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
268	     *
269	     * @param value the value to hash
270	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
271	     */
272	    private static String sha256Hex8(String value) {
273	        try {
274	            byte[] digest = MessageDigest.getInstance("SHA-256")
275	                .digest(value.getBytes(StandardCharsets.UTF_8));
276	            StringBuilder hex = new StringBuilder(8);
277	            for (int i = 0; i < 4; i++) {
278	                hex.append(String.format("%02X", digest[i]));
279	            }
280	            return hex.toString();
281	        }
282	        catch (NoSuchAlgorithmException e) {
283	            throw new IllegalStateException("SHA-256 algorithm not available", e);
284	        }
285	    }
286	
287	    /**
288	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
289	     * absent, not a 4-digit number, or in no known range.
290	     *
291	     * @return the matching region, or {@code null}
292	     */
293	    private String regionFromPostcode() {
294	        if (this.postcode == null) {
295	            return null;
296	        }
297	        int value;
298	        try {
299	            value = Integer.parseInt(this.postcode.trim());
300	        }
301	        catch (NumberFormatException ex) {
302	            return null;
303	        }
304	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
305	            int[] range = entry.getValue();
306	            if (value >= range[0] && value <= range[1]) {
307	                return entry.getKey();
308	            }
309	        }
310	        return null;
311	    }
312	
313	    /**
314	     * The owner's preferred contact channel, derived from the owner's details. Returns
315	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
316	     *
317	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
318	     */
319	    public String getContactPreference() {
320	        boolean hasEmail = this.email != null && !this.email.isBlank();
321	        return hasEmail ? "EMAIL" : "PHONE";
322	    }
323	
324	    /**
325	     * The owner's identity key, the single derived value used for duplicate detection. It is the
326	     * owner's normalized telephone, email (empty when absent) and household id joined with
327	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
328	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
329	     * are equal, so two members of the same household with different telephones differ here and are
330	     * both allowed.
331	     *
332	     * @return the derived identity key
333	     */
334	    public String getIdentityKey() {
335	        return (this.telephone == null ? "" : this.telephone) + "|"
336	            + (this.email == null ? "" : this.email) + "|"
337	            + (this.householdId == null ? "" : this.householdId);
338	    }
339	
340	    public String getHouseholdId() {
341	        return this.householdId;
342	    }
343	
344	    public void setHouseholdId(String householdId) {
345	        this.householdId = householdId;
346	    }
347	
348	    public Integer getNamesakeCount() {
349	        return this.namesakeCount;
350	    }
351	
352	    public void setNamesakeCount(Integer namesakeCount) {
353	        this.namesakeCount = namesakeCount;
354	    }
355	
356	    public Integer getHouseholdSize() {
357	        return this.householdSize;
358	    }
359	
360	    public void setHouseholdSize(Integer householdSize) {
361	        this.householdSize = householdSize;
362	    }
363	
364	    public String getPostcode() {
365	        return this.postcode;
366	    }
367	
368	    public void setPostcode(String postcode) {
369	        this.postcode = postcode;
370	    }
371	
372	    public Boolean getBulkSignupWarning() {
373	        return this.bulkSignupWarning;
374	    }
375	
376	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
377	        this.bulkSignupWarning = bulkSignupWarning;
378	    }
379	
380	    /**
381	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
382	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
383	     */
384	    @PrePersist
385	    void onCreate() {
386	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
387	    }
388	
389	    /**
390	     * Resolves the effective registration date and rolls it onto a business day. An absent
391	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
392	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
393	     * becomes the following Monday, while any weekday is returned unchanged.
394	     *
395	     * <p>This is the single definition of both the defaulting and the business-day roll, used
396	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
397	     * stamps the owner and by the create endpoint that counts owners per business day.
398	     *
399	     * @param supplied the registration date from the request, or {@code null} when none was supplied
400	     * @return the effective registration date, guaranteed to fall on a business day
401	     */
402	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
403	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
404	        return switch (effective.getDayOfWeek()) {
405	            case SATURDAY -> effective.plusDays(2);
406	            case SUNDAY -> effective.plusDays(1);
407	            default -> effective;
408	        };
409	    }
410	
411	    protected Set<Pet> getPetsInternal() {
412	        if (this.pets == null) {
413	            this.pets = new HashSet<>();
414	        }
415	        return this.pets;
416	    }
417	
418	    protected void setPetsInternal(Set<Pet> pets) {
419	        this.pets = pets;
420	    }
421	
422	    public List<Pet> getPets() {
423	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
424	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
425	        return Collections.unmodifiableList(sortedPets);
426	    }
427	
428	    public void setPets(List<Pet> pets) {
429	        this.pets = new HashSet<>(pets);
430	    }
431	
432	    public void addPet(Pet pet) {
433	        getPetsInternal().add(pet);
434	        pet.setOwner(this);
435	    }
436	
437	    /**
438	     * Return the Pet with the given name, or null if none found for this Owner.
439	     *
440	     * @param name to test
441	     * @return true if pet name is already in use
442	     */
443	    public Pet getPet(String name) {
444	        return getPet(name, false);
445	    }
446	
447	    /**
448	     * Return the Pet with the given name, or null if none found for this Owner.
449	     *
450	     * @param name to test
451	     * @return true if pet name is already in use
452	     */
453	    public Pet getPet(String name, boolean ignoreNew) {
454	        name = name.toLowerCase();
455	        for (Pet pet : getPetsInternal()) {
456	            if (!ignoreNew || !pet.isNew()) {
457	                String compName = pet.getName();
458	                compName = compName.toLowerCase();
459	                if (compName.equals(name)) {
460	                    return pet;
461	                }
462	            }
463	        }
464	        return null;
465	    }
466	
467	    public Pet getPet(Integer petId) {
468	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
469	    }
470	
471	    @Override
472	    public String toString() {
473	        return new ToStringCreator(this)
474	
475	            .append("id", this.getId())
476	            .append("new", this.isNew())
477	            .append("lastName", this.getLastName())
478	            .append("firstName", this.getFirstName())
479	            .append("address", this.address)
480	            .append("city", this.city)
481	            .append("telephone", this.telephone)
482	            .toString();
483	    }
484	}
